package dev.asad.bookshelf;import jakarta.validation.Valid;import org.springframework.http.HttpStatus;import org.springframework.web.bind.annotation.*;import org.springframework.web.server.ResponseStatusException;import java.util.List;
@RestController @RequestMapping("/api/entries") @CrossOrigin(origins={"http://localhost:5173","http://127.0.0.1:5173"}) public class EntryController{private final EntryRepository repository;public EntryController(EntryRepository r){repository=r;}@GetMapping public List<Entry> list(@RequestParam(required=false)String search){var all=repository.findAll();return search==null||search.isBlank()?all:all.stream().filter(x->x.getTitle().toLowerCase().contains(search.toLowerCase())).toList();}@GetMapping("/{id}")public Entry get(@PathVariable Long id){return find(id);}@PostMapping @ResponseStatus(HttpStatus.CREATED)public Entry create(@Valid @RequestBody Entry x){x.setId(null);return repository.save(x);}@PutMapping("/{id}")public Entry update(@PathVariable Long id,@Valid @RequestBody Entry x){var old=find(id);x.setId(old.getId());return repository.save(x);}@PatchMapping("/{id}/status")public Entry status(@PathVariable Long id,@RequestParam String status){var x=find(id);x.setStatus(status);return repository.save(x);}@DeleteMapping("/{id}")@ResponseStatus(HttpStatus.NO_CONTENT)public void delete(@PathVariable Long id){repository.delete(find(id));}private Entry find(Long id){return repository.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Entry not found"));}}
